const req = $('When Executed by Another Workflow').first().json;
const draft = $input.first().json;
if (!draft.id) throw new Error('draft_not_found');
if (draft.status !== 'approved') throw new Error('draft_not_approved');
if (Number(req.approved_version) !== Number(draft.approved_version)) throw new Error('approved_version_mismatch');
const stop = (status, message) => [{ json: { allowed: false, result: { status, draft_id: draft.id, approved_version: Number(req.approved_version), message } } }];
const raw = String(req.publish_at || '').trim();
const publishNow = req.publish_now === true || String(req.publish_now).toLowerCase() === 'true';
if (req.trigger_source === 'scheduler') {
  // Lần chạy của Scheduled Publisher: admin đã xác nhận lúc hẹn giờ; job được kiểm ở Decide Job và giành nguyên tử ở Claim Job.
  if (!String(req.job_id || '').trim()) throw new Error('job_id_required');
} else {
  // Xác nhận chỉ lấy từ tin nhắn thật của admin ở lượt này (main workflow gắn cố định, model không điền được).
  const text = String(req.confirmation_text || '').normalize('NFC').toLowerCase();
  const L = '(?<![\\p{L}\\p{N}_])';
  const R = '(?![\\p{L}\\p{N}_])';
  const words = '(?:đăng|xuất bản|publish|lên lịch|hẹn giờ|hẹn|lên bài|schedule)';
  const publishRe = new RegExp(L + words + R, 'u');
  const negatedRe = new RegExp(L + '(?:đừng|chớ|chưa|không|khoan|hủy|huỷ|bỏ|dừng|don\'t|do not|not|never|cancel)\\s+(?:được\\s+|nên\\s+|cần\\s+|vội\\s+|phải\\s+)*' + words + R, 'u');
  const immediateRe = new RegExp(L + '(?:ngay lập tức|ngay|luôn|bây giờ|hiện tại|lập tức|liền|now|immediately|go live|đăng đi|xuất bản đi)' + R, 'u');
  if (!publishRe.test(text) || negatedRe.test(text)) {
    return stop('needs_admin_confirmation', 'Tin nhắn hiện tại của admin chưa yêu cầu đăng hoặc hẹn giờ đăng rõ ràng (ví dụ "đăng luôn", "đăng lúc 8h sáng mai"). Hãy hỏi admin và chờ tin nhắn xác nhận của họ. Không tự đăng.');
  }
  // Duyệt và đăng phải ở hai lượt chat khác nhau: bản vừa được duyệt trong chính lượt này thì admin chưa xác nhận đăng.
  const turnMs = Date.parse(req.turn_started_at);
  if (Number.isNaN(turnMs)) throw new Error('turn_started_at_missing: không xác định được thời điểm bắt đầu lượt chat nên không thể đăng');
  const approvedMs = Date.parse(draft.approved_at);
  const SKEW_MS = 5000; // dung sai lệch đồng hồ n8n/Supabase, nghiêng về phía từ chối
  if (Number.isNaN(approvedMs) || approvedMs >= turnMs - SKEW_MS) {
    return stop('needs_admin_confirmation', 'Bản nháp vừa được duyệt ở lượt này; cần admin xác nhận đăng bằng một tin nhắn riêng ở lượt sau (đăng ngay hay hẹn giờ).');
  }
  if (!raw && publishNow && !immediateRe.test(text)) {
    return stop('needs_admin_confirmation', 'Admin chưa nói rõ đăng ngay hay hẹn giờ. Hãy hỏi admin muốn đăng lúc nào, hoặc "đăng luôn" nếu đăng ngay.');
  }
}
if (!raw && !publishNow) throw new Error('publish_time_or_publish_now_required');
let runAt = new Date();
if (raw) {
  const withT = raw.replace(/^(\d{4}-\d{2}-\d{2})\s+/, '$1T');
  const hasZone = /(Z|[+-]\d{2}:?\d{2})$/i.test(withT);
  const t = Date.parse((hasZone ? withT : (/^\d{4}-\d{2}-\d{2}$/.test(withT) ? withT + 'T00:00:00' : withT) + '+07:00'));
  if (Number.isNaN(t)) throw new Error('invalid_datetime: publish_at=' + raw);
  if (t < Date.now() - 5 * 60000) throw new Error('publish_at_in_past: thời gian đăng đã qua, hãy hỏi lại admin.');
  runAt = new Date(t);
}
const due = runAt.getTime() <= Date.now() + 60000;
return [{ json: { allowed: true, ...req, publish_now: publishNow, run_at: runAt.toISOString(), due } }];

const ctx = $('Validate Publish').first().json;
const job = $input.first().json;
const now = Date.now();
const stopWith = (base, result) => [{ json: { ...base, action: 'stop', result } }];
if (!job.id) {
  if (ctx.trigger_source === 'scheduler') return stopWith(ctx, { status: 'job_not_found', message: 'Không tìm thấy job để chạy theo lịch.' });
  return [{ json: { ...ctx, action: 'create' } }];
}
const base = { ...ctx, job };
const stop = result => stopWith(base, result);
const info = { publication_job_id: job.id, channel: job.channel, provider_post_id: job.provider_post_id || null, published_url: job.published_url || null, publish_at: job.publish_at || null };
if (job.status === 'published') return stop({ ...info, status: 'already_published', message: 'Kênh này đã đăng version này, không đăng lại.' });
if (job.status === 'cancelled') return stop({ ...info, status: 'job_cancelled', message: 'Job đăng của kênh này đã bị hủy, không tự đăng lại. Hãy hỏi admin.' });
if (ctx.trigger_source === 'scheduler') {
  if (job.id !== ctx.job_id || job.status !== 'scheduled') return stop({ ...info, status: 'skipped', message: 'Job không còn ở trạng thái scheduled, bỏ qua lần chạy theo lịch.' });
}
if (job.status === 'scheduled') {
  if (Date.parse(job.publish_at) <= now + 60000) return [{ json: { ...base, action: 'claim' } }];
  return stop({ ...info, status: 'already_scheduled', message: 'Version này đã được lên lịch cho kênh này, chưa thể đổi giờ qua tool.' });
}
const retryable = job.status === 'failed' || now - Date.parse(job.updated_at || job.created_at) > 10 * 60000;
if (!retryable) return stop({ ...info, status: 'in_progress', message: 'Kênh này đang được đăng, hãy kiểm tra lại sau ít phút.' });
// failed hoặc kẹt quá 10 phút: đến hạn thì giành job đăng luôn; chưa đến hạn thì đặt lại lịch.
return [{ json: { ...base, action: ctx.due ? 'claim' : 'reschedule' } }];

const ctx = $('Decide Job').first().json;
const src = $input.first().json;
const jobId = ctx.action === 'claim' ? ctx.job.id : src.id;
if (!jobId) throw new Error('job_changed_concurrently: job vừa được execution khác thay đổi, hãy kiểm tra lại trạng thái rồi thử lại.');
return [{ json: { ...ctx, job_id: jobId } }];

const req = $('Job Ready').first().json;
const version = $input.first().json;
if (!version.id) throw new Error('version_not_found');
const p = typeof version.threads_payload === 'string' ? JSON.parse(version.threads_payload) : (version.threads_payload || {});
const text = String(p.text || p.content || '').trim();
if (!text) throw new Error('threads_text_required');
if (text.length > 500) throw new Error('threads_text_too_long: tối đa 500 ký tự');
const image = p.image_url || (version.images || [])[0]?.url;
if (!image || !String(image).startsWith('https://')) throw new Error('public_https_image_required');
return [{ json: { ...req, text, image_url: image } }];

const prepared = $('Prepare Threads Post').first().json;
const rows = $input.all().map(item => item.json).filter(row => row && row.id);
if (rows.length === 1) return [{ json: { ...prepared, claimed: true, claimed_job: rows[0] } }];
return [{ json: { claimed: false, job_id: prepared.job_id, channel: 'threads' } }];

const x = $('Evaluate Claim').first().json;
const job = $input.first().json;
const info = { publication_job_id: x.job_id, channel: x.channel, provider_post_id: job.provider_post_id || null, published_url: job.published_url || null };
if (job.status === 'published') return [{ json: { ...info, status: 'already_published', message: 'Kênh này đã được đăng bởi một lượt chạy khác, không đăng lại.' } }];
return [{ json: { ...info, status: 'in_progress', message: 'Một lượt chạy khác đang đăng hoặc đã xử lý job này, không đăng trùng. Hãy kiểm tra lại sau ít phút.' } }];
